  public var RING_ROLES: FlatbufferVector<avlRingRole> { return _accessor.vector(at: VT.RING_ROLES, byteSize: 1) }
  ///  Number of polygons; equals max(RING_POLYGON_INDEXES) + 1, published so
  ///  an empty geometry is distinguishable from an unpopulated record.
  public var POLYGON_COUNT: UInt32 { let o = _accessor.offset(VT.POLYGON_COUNT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  The source's arc or circle boundary segments were densified into the
  ///  vertices above by the ingest.
  public var ARC_DENSIFIED: Bool { let o = _accessor.offset(VT.ARC_DENSIFIED); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Maximum deviation, metres, between a densified chord and the published
  ///  arc. Required knowledge when ARC_DENSIFIED; NaN otherwise.
  public var DENSIFICATION_TOLERANCE_M: Double { let o = _accessor.offset(VT.DENSIFICATION_TOLERANCE_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Dataset lineage and licence. Required.
  public var SOURCE: AVLProvenance! { let o = _accessor.offset(VT.SOURCE); return AVLProvenance(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startAVL(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 22) }
  public static func add(ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ID, at: VT.ID) }
  public static func add(DESIGNATOR: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DESIGNATOR, at: VT.DESIGNATOR) }
  public static func add(NAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: NAME, at: VT.NAME) }
  public static func add(AIRSPACE_CLASS: avlAirspaceClass, _ fbb: inout FlatBufferBuilder) { fbb.add(element: AIRSPACE_CLASS.rawValue, def: 0, at: VT.AIRSPACE_CLASS) }
  public static func add(VOLUME_TYPE: avlVolumeType, _ fbb: inout FlatBufferBuilder) { fbb.add(element: VOLUME_TYPE.rawValue, def: 0, at: VT.VOLUME_TYPE) }
  public static func add(COUNTRY_CODE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: COUNTRY_CODE, at: VT.COUNTRY_CODE) }
  public static func add(FLOOR_VALUE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: FLOOR_VALUE, def: 0.0, at: VT.FLOOR_VALUE) }
  public static func add(FLOOR_DATUM: avlVerticalDatum, _ fbb: inout FlatBufferBuilder) { fbb.add(element: FLOOR_DATUM.rawValue, def: 0, at: VT.FLOOR_DATUM) }
  public static func add(CEILING_VALUE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CEILING_VALUE, def: 0.0, at: VT.CEILING_VALUE) }
  public static func add(CEILING_DATUM: avlVerticalDatum, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CEILING_DATUM.rawValue, def: 0, at: VT.CEILING_DATUM) }
  public static func add(EFFECTIVE_FROM: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EFFECTIVE_FROM, at: VT.EFFECTIVE_FROM) }
  public static func add(EFFECTIVE_TO: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EFFECTIVE_TO, at: VT.EFFECTIVE_TO) }
  public static func add(TIME_OF_ACTIVITY: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TIME_OF_ACTIVITY, at: VT.TIME_OF_ACTIVITY) }
  public static func addVectorOf(VERTEX_LONGITUDE_DEG: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: VERTEX_LONGITUDE_DEG, at: VT.VERTEX_LONGITUDE_DEG) }
  public static func addVectorOf(VERTEX_LATITUDE_DEG: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: VERTEX_LATITUDE_DEG, at: VT.VERTEX_LATITUDE_DEG) }
  public static func addVectorOf(RING_OFFSETS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RING_OFFSETS, at: VT.RING_OFFSETS) }
  public static func addVectorOf(RING_POLYGON_INDEXES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RING_POLYGON_INDEXES, at: VT.RING_POLYGON_INDEXES) }
  public static func addVectorOf(RING_ROLES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: RING_ROLES, at: VT.RING_ROLES) }
  public static func add(POLYGON_COUNT: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: POLYGON_COUNT, def: 0, at: VT.POLYGON_COUNT) }
  public static func add(ARC_DENSIFIED: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ARC_DENSIFIED, def: false,
   at: VT.ARC_DENSIFIED) }
  public static func add(DENSIFICATION_TOLERANCE_M: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DENSIFICATION_TOLERANCE_M, def: 0.0, at: VT.DENSIFICATION_TOLERANCE_M) }
  public static func add(SOURCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOURCE, at: VT.SOURCE) }
  public static func endAVL(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4, 30, 32, 34, 36, 38, 46]); return end }
  public static func createAVL(
    _ fbb: inout FlatBufferBuilder,
    IDOffset ID: Offset,
    DESIGNATOROffset DESIGNATOR: Offset = Offset(),
    NAMEOffset NAME: Offset = Offset(),
    AIRSPACE_CLASS: avlAirspaceClass = .unspecified,
    VOLUME_TYPE: avlVolumeType = .unspecified,
    COUNTRY_CODEOffset COUNTRY_CODE: Offset = Offset(),
    FLOOR_VALUE: Double = 0.0,
    FLOOR_DATUM: avlVerticalDatum = .unspecified,
    CEILING_VALUE: Double = 0.0,
    CEILING_DATUM: avlVerticalDatum = .unspecified,
    EFFECTIVE_FROMOffset EFFECTIVE_FROM: Offset = Offset(),
    EFFECTIVE_TOOffset EFFECTIVE_TO: Offset = Offset(),
    TIME_OF_ACTIVITYOffset TIME_OF_ACTIVITY: Offset = Offset(),
    VERTEX_LONGITUDE_DEGVectorOffset VERTEX_LONGITUDE_DEG: Offset,
    VERTEX_LATITUDE_DEGVectorOffset VERTEX_LATITUDE_DEG: Offset,
    RING_OFFSETSVectorOffset RING_OFFSETS: Offset,
    RING_POLYGON_INDEXESVectorOffset RING_POLYGON_INDEXES: Offset,
    RING_ROLESVectorOffset RING_ROLES: Offset,
    POLYGON_COUNT: UInt32 = 0,
    ARC_DENSIFIED: Bool = false,
    DENSIFICATION_TOLERANCE_M: Double = 0.0,
    SOURCEOffset SOURCE: Offset
  ) -> Offset {
    let __start = AVL.startAVL(&fbb)
    AVL.add(ID: ID, &fbb)
    AVL.add(DESIGNATOR: DESIGNATOR, &fbb)
    AVL.add(NAME: NAME, &fbb)
    AVL.add(AIRSPACE_CLASS: AIRSPACE_CLASS, &fbb)
    AVL.add(VOLUME_TYPE: VOLUME_TYPE, &fbb)
    AVL.add(COUNTRY_CODE: COUNTRY_CODE, &fbb)
    AVL.add(FLOOR_VALUE: FLOOR_VALUE, &fbb)
    AVL.add(FLOOR_DATUM: FLOOR_DATUM, &fbb)
    AVL.add(CEILING_VALUE: CEILING_VALUE, &fbb)
    AVL.add(CEILING_DATUM: CEILING_DATUM, &fbb)
    AVL.add(EFFECTIVE_FROM: EFFECTIVE_FROM, &fbb)
    AVL.add(EFFECTIVE_TO: EFFECTIVE_TO, &fbb)
    AVL.add(TIME_OF_ACTIVITY: TIME_OF_ACTIVITY, &fbb)
    AVL.addVectorOf(VERTEX_LONGITUDE_DEG: VERTEX_LONGITUDE_DEG, &fbb)
    AVL.addVectorOf(VERTEX_LATITUDE_DEG: VERTEX_LATITUDE_DEG, &fbb)
    AVL.addVectorOf(RING_OFFSETS: RING_OFFSETS, &fbb)
    AVL.addVectorOf(RING_POLYGON_INDEXES: RING_POLYGON_INDEXES, &fbb)
    AVL.addVectorOf(RING_ROLES: RING_ROLES, &fbb)
    AVL.add(POLYGON_COUNT: POLYGON_COUNT, &fbb)
    AVL.add(ARC_DENSIFIED: ARC_DENSIFIED, &fbb)
    AVL.add(DENSIFICATION_TOLERANCE_M: DENSIFICATION_TOLERANCE_M, &fbb)
    AVL.add(SOURCE: SOURCE, &fbb)
    return AVL.endAVL(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ID, fieldName: "ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.DESIGNATOR, fieldName: "DESIGNATOR", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.AIRSPACE_CLASS, fieldName: "AIRSPACE_CLASS", required: false, type: avlAirspaceClass.self)
    try _v.visit(field: VT.VOLUME_TYPE, fieldName: "VOLUME_TYPE", required: false, type: avlVolumeType.self)
    try _v.visit(field: VT.COUNTRY_CODE, fieldName: "COUNTRY_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FLOOR_VALUE, fieldName: "FLOOR_VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.FLOOR_DATUM, fieldName: "FLOOR_DATUM", required: false, type: avlVerticalDatum.self)
    try _v.visit(field: VT.CEILING_VALUE, fieldName: "CEILING_VALUE", required: false, type: Double.self)
    try _v.visit(field: VT.CEILING_DATUM, fieldName: "CEILING_DATUM", required: false, type: avlVerticalDatum.self)
    try _v.visit(field: VT.EFFECTIVE_FROM, fieldName: "EFFECTIVE_FROM", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.EFFECTIVE_TO, fieldName: "EFFECTIVE_TO", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.TIME_OF_ACTIVITY, fieldName: "TIME_OF_ACTIVITY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.VERTEX_LONGITUDE_DEG, fieldName: "VERTEX_LONGITUDE_DEG", required: true, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.VERTEX_LATITUDE_DEG, fieldName: "VERTEX_LATITUDE_DEG", required: true, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.RING_OFFSETS, fieldName: "RING_OFFSETS", required: true, type: ForwardOffset<Vector<UInt32, UInt32>>.self)
    try _v.visit(field: VT.RING_POLYGON_INDEXES, fieldName: "RING_POLYGON_INDEXES", required: true, type: ForwardOffset<Vector<UInt32, UInt32>>.self)
    try _v.visit(field: VT.RING_ROLES, fieldName: "RING_ROLES", required: true, type: ForwardOffset<Vector<avlRingRole, avlRingRole>>.self)
    try _v.visit(field: VT.POLYGON_COUNT, fieldName: "POLYGON_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.ARC_DENSIFIED, fieldName: "ARC_DENSIFIED", required: false, type: Bool.self)
    try _v.visit(field: VT.DENSIFICATION_TOLERANCE_M, fieldName: "DENSIFICATION_TOLERANCE_M", required: false, type: Double.self)
    try _v.visit(field: VT.SOURCE, fieldName: "SOURCE", required: true, type: ForwardOffset<AVLProvenance>.self)
    _v.finish()
  }
}
